        cands.append(a.astimezone(UTC).replace(tzinfo=None))
    lo, hi = min(cands), max(cands)
    # hi is in the after-jump offset; find first minute where offset equals offset at hi
    off_after = hi.replace(tzinfo=UTC).astimezone(z).utcoffset()
    a, b = lo.replace(tzinfo=UTC), hi.replace(tzinfo=UTC)
    while a < b:
        m = a + (b - a) // 2
        m = m.replace(second=0, microsecond=0)
        if m <= a: m = a + dt.timedelta(minutes=1)
        if m > b: m = b
        if m.astimezone(z).utcoffset() == off_after:
            b = m
        else:
            a = m
        if b - a <= dt.timedelta(minutes=1):
            break
    # b is first minute with after-offset
    return b.replace(tzinfo=None)

